FALL = 3   # Fehlschläge bis "down"

status = {"web1": "up", "web2": "up"}
fehler = {"web1": 0, "web2": 0}

def check(name, ok):
    if ok:
        fehler[name] = 0
        status[name] = "up"
    else:
        fehler[name] += 1
        if fehler[name] >= FALL:
            status[name] = "down"

for ok in [False, False, True,
           False, False, False]:
    check("web2", ok)
print(status, fehler)

# Ausgabe:
# {'web1': 'up', 'web2': 'down'} {'web1': 0, 'web2': 3}
